#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char *argv[]) {
    // No arguments besides program name
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }
    // Only the x argument, no coefficients
    if (argc == 2) {
        puts("EMPTY");
        return 0;
    }
    // The original binary limits the total number of arguments to 14 (program name + x + up to 12 coefficients).
    // If more arguments are supplied, it reports OUT_OF_RANGE.
    if (argc > 14) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    // Parse the first argument (x).
    char *endptr;
    long long x = strtoll(argv[1], &endptr, 10);
    if (*endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    // The original program only accepts x in the range [-inf, 10]. Values greater than 10 are out of range.
    if (x > 10) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    // Parse coefficients.
    int coeff_count = argc - 2;
    long long coeffs[12]; // maximum 12 coefficients (since argc <= 14)
    for (int i = 0; i < coeff_count; ++i) {
        long long v = strtoll(argv[2 + i], &endptr, 10);
        if (*endptr != '\0') {
            puts("BAD_INPUT");
            return 0;
        }
        coeffs[i] = v; // store as‑is (negative values are allowed)
    }

    // Horner's method evaluation.
    long long result = 0;
    for (int i = 0; i < coeff_count; ++i) {
        result = result * x + coeffs[i];
    }
    printf("%lld\n", result);
    return 0;
}
